const toggle=document.querySelector('#menu-toggle');
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');document.querySelector('#navigation').classList.toggle('open',open);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open navigation');document.querySelector('#navigation').classList.remove('open');}});
const dialog=document.createElement('dialog');dialog.className='lightbox';dialog.setAttribute('aria-label','Photo viewer');dialog.innerHTML='<button class="lightbox-close" aria-label="Close photo">&times;</button><figure><img alt=""><figcaption></figcaption></figure>';document.body.append(dialog);
let opener;
document.querySelectorAll('main img').forEach(img=>{img.tabIndex=0;img.setAttribute('role','button');img.setAttribute('aria-label','View photo: '+img.alt);const open=e=>{e.preventDefault();e.stopPropagation();opener=img;dialog.querySelector('img').src=img.currentSrc||img.src;dialog.querySelector('img').alt=img.alt;dialog.querySelector('figcaption').textContent=img.alt;dialog.showModal();document.body.style.overflow='hidden';};img.addEventListener('click',open);img.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')open(e);});});
dialog.querySelector('.lightbox-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});dialog.addEventListener('close',()=>{document.body.style.overflow='';opener?.focus();});
const topButton=document.createElement('button');topButton.className='back-to-top';topButton.setAttribute('aria-label','Back to top');topButton.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 7-7 7 7M12 5v15"/></svg>';topButton.hidden=true;document.body.append(topButton);const updateTop=()=>{topButton.hidden=scrollY<400;};window.addEventListener('scroll',updateTop,{passive:true});updateTop();topButton.onclick=()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{const selected=b===button;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected));});let count=0;document.querySelectorAll('[data-category]').forEach(section=>{section.hidden=button.dataset.filter!=='all'&&section.dataset.category!==button.dataset.filter;if(!section.hidden)count+=section.querySelectorAll('img').length;});document.querySelector('.gallery-count').textContent=count+' photographs';}));
document.querySelector('[data-filter="all"]')?.click();
const arrival=document.querySelector('[name="arrival"]'),departure=document.querySelector('[name="departure"]');
if(arrival){const today=new Date();today.setMinutes(today.getMinutes()-today.getTimezoneOffset());arrival.min=today.toISOString().slice(0,10);arrival.addEventListener('change',()=>{const next=new Date(arrival.value+'T12:00:00');next.setDate(next.getDate()+1);departure.min=next.toISOString().slice(0,10);});}
document.querySelector('#enquiry')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);if(d.get('departure')<=d.get('arrival')){document.querySelector('#form-status').textContent='Please choose a departure date after your arrival.';return;}const body=`Name: ${d.get('name')}\nEmail: ${d.get('email')}\nRetreat: ${d.get('type')}\nArrival: ${d.get('arrival')}\nDeparture: ${d.get('departure')}\nFlexible dates: ${d.get('flexible')||'No'}\nGroup size: ${d.get('guests')}\n\n${d.get('message')}`;location.href='mailto:himalayanhempecostay@gmail.com?subject=Retreat%20enquiry&body='+encodeURIComponent(body);document.querySelector('#form-status').textContent='Please review and send the enquiry in your email app. If it does not open, contact us by WhatsApp.';});
